import { m } from "motion/react";
import { cn } from "@/lib/utils";
import { spring } from "@/motion/presets";
import { useId } from "react";

/** 分段切换: 滑块跟随. 时间范围 / 视图切换. */
export function Segmented<T extends string>({ options, value, onChange, className }: {
  options: { value: T; label: string }[];
  value: T;
  onChange: (v: T) => void;
  className?: string;
}) {
  const id = useId();
  return (
    <div role="tablist" className={cn("inline-flex rounded-lg bg-muted p-0.5", className)}>
      {options.map((o) => {
        const on = o.value === value;
        return (
          <button
            key={o.value}
            type="button"
            role="tab"
            aria-selected={on}
            onClick={() => onChange(o.value)}
            className={cn("relative h-7 rounded-md px-3 text-xs font-medium transition-colors", on ? "text-foreground" : "text-muted-foreground hover:text-foreground")}
          >
            {on && <m.span layoutId={`seg-${id}`} transition={spring.snappy} className="absolute inset-0 rounded-md bg-background shadow-soft" />}
            <span className="relative">{o.label}</span>
          </button>
        );
      })}
    </div>
  );
}

import type * as React from "react";
import { Reveal } from "@/motion/reveal";
import { cn } from "@/lib/utils";

/**
 * 收尾号召: 大标题 + 按钮, 不加光晕色块.
 * media 可放一张产品局部, 在右侧 / 下方露出.
 */
export function Cta({ title, description, actions, media, className }: {
  title: React.ReactNode;
  description?: string;
  actions?: React.ReactNode;
  media?: React.ReactNode;
  className?: string;
}) {
  return (
    <section className={cn("border-t px-5 py-24 md:px-8 md:py-32", className)}>
      <Reveal className={cn("mx-auto max-w-6xl", media && "grid items-center gap-12 lg:grid-cols-2")}>
        <div>
          <h2 className="max-w-2xl text-balance text-4xl font-medium leading-[1.06] tracking-[-0.03em] md:text-6xl">{title}</h2>
          {description && <p className="mt-6 max-w-lg text-pretty text-[17px] leading-relaxed text-muted-foreground">{description}</p>}
          {actions && <div className="mt-9 flex flex-wrap items-center gap-x-5 gap-y-3">{actions}</div>}
        </div>
        {media}
      </Reveal>
    </section>
  );
}

import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion";
import { cn } from "@/lib/utils";

/** 常见问题: 手风琴. 放在 Section layout="split" 的右栏里最好看. */
export function Faq({ items, className }: { items: { q: string; a: string }[]; className?: string }) {
  return (
    <Accordion type="single" collapsible className={cn("border-t", className)}>
      {items.map((it, i) => (
        <AccordionItem key={i} value={`q${i}`}>
          <AccordionTrigger className="py-5 text-left text-[15px] font-medium hover:no-underline">{it.q}</AccordionTrigger>
          <AccordionContent className="pb-5 leading-relaxed text-muted-foreground">{it.a}</AccordionContent>
        </AccordionItem>
      ))}
    </Accordion>
  );
}

import type * as React from "react";
import { Stagger, StaggerItem } from "@/motion/reveal";
import { cn } from "@/lib/utils";

export interface GridFeature {
  title: string;
  description: string;
  icon?: React.ComponentType<{ className?: string }>;
}

/** 特性网格: 发丝线分隔, 小图标与标题同行, 不用彩色图标底块. */
export function FeatureGrid({ features, columns = 3, className }: { features: GridFeature[]; columns?: 2 | 3 | 4; className?: string }) {
  const cols = { 2: "sm:grid-cols-2", 3: "sm:grid-cols-2 lg:grid-cols-3", 4: "sm:grid-cols-2 lg:grid-cols-4" }[columns];
  return (
    <Stagger gap={0.05} className={cn("grid gap-px overflow-hidden rounded-xl border bg-border", cols, className)}>
      {features.map((f) => (
        <StaggerItem key={f.title} className="bg-background p-6 md:p-7">
          <h3 className="flex items-center gap-2 text-[15px] font-medium">
            {f.icon && <f.icon className="size-4 text-muted-foreground" />}
            {f.title}
          </h3>
          <p className="mt-2 text-sm leading-relaxed text-muted-foreground">{f.description}</p>
        </StaggerItem>
      ))}
    </Stagger>
  );
}

import * as React from "react";
import { AnimatePresence, m, useInView } from "motion/react";
import { useReducedMotion } from "@/motion/use-reduced-motion";
import { cn } from "@/lib/utils";

export interface FeatureTab {
  title: string;
  description: string;
  /** 右侧视觉: 活组件优先, 其次截图 */
  visual: React.ReactNode;
}

/**
 * 特性轮播: 左侧条目 + 右侧视觉, 自动前进, 当前条目底部有进度线.
 * 悬停 / 聚焦暂停; 减弱动效时不自动前进, 视觉直接切换.
 */
export function FeatureTabs({ tabs, interval = 7000, className }: { tabs: FeatureTab[]; interval?: number; className?: string }) {
  const [i, setI] = React.useState(0);
  const [paused, setPaused] = React.useState(false);
  const ref = React.useRef<HTMLDivElement>(null);
  const inView = useInView(ref, { margin: "-20% 0px" });
  const reduce = useReducedMotion();
  const auto = !reduce && !paused && inView;

  React.useEffect(() => {
    if (!auto) return;
    const t = window.setTimeout(() => setI((v) => (v + 1) % tabs.length), interval);
    return () => window.clearTimeout(t);
  }, [auto, i, interval, tabs.length]);

  return (
    <div ref={ref} className={cn("grid gap-8 lg:grid-cols-[minmax(0,4fr)_minmax(0,8fr)] lg:gap-12", className)} onMouseEnter={() => setPaused(true)} onMouseLeave={() => setPaused(false)}>
      <div role="tablist" aria-orientation="vertical" className="flex flex-col">
        {tabs.map((t, k) => {
          const on = k === i;
          return (
            <button
              key={t.title}
              type="button"
              role="tab"
              aria-selected={on}
              onClick={() => setI(k)}
              onFocus={() => setPaused(true)}
              onBlur={() => setPaused(false)}
              className={cn("relative border-t py-5 text-left transition-colors", on ? "border-foreground/15" : "border-border")}
            >
              <span aria-hidden className="absolute -top-px left-0 h-px w-full overflow-hidden">
                {on && (
                  <span
                    key={`${i}-${auto}`}
                    className={cn("block h-full origin-left bg-foreground", auto ? "animate-[hx-progress_linear_forwards]" : "")}
                    style={auto ? { animationDuration: `${interval}ms` } : undefined}
                  />
                )}
              </span>
              <div className={cn("font-medium transition-colors", on ? "text-foreground" : "text-muted-foreground")}>{t.title}</div>
              <div className={cn("grid transition-[grid-template-rows,opacity] duration-300", on ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0")}>
                <p className="overflow-hidden text-sm leading-relaxed text-muted-foreground"><span className="block pt-2">{t.description}</span></p>
              </div>
            </button>
          );
        })}
      </div>
      <div className="relative min-w-0">
        <AnimatePresence mode="wait" initial={false}>
          <m.div
            key={i}
            role="tabpanel"
            initial={reduce ? false : { opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            exit={reduce ? undefined : { opacity: 0, y: -8 }}
            transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
          >
            {tabs[i].visual}
          </m.div>
        </AnimatePresence>
      </div>
    </div>
  );
}

import * as React from "react";
import { ArrowRight } from "lucide-react";
import { m, useScroll, useTransform } from "motion/react";
import { useReducedMotion } from "@/motion/use-reduced-motion";
import { Reveal } from "@/motion/reveal";
import { Backdrop } from "@/effects/backdrop";
import { cn } from "@/lib/utils";

interface HeroProps {
  eyebrow?: { label: string; href?: string };
  title: string;
  /** 第二行, 用弱化色; 主次两句话的写法, 不再做渐变字 */
  highlight?: string;
  description: string;
  actions?: React.ReactNode;
  /** 产品界面 / 活组件 / 视频 */
  media?: React.ReactNode;
  align?: "center" | "left";
  /** 背景: 默认无. 成熟发布页靠排版和产品图撑场面, 不靠光晕 */
  backdrop?: "grid" | "dots" | "aurora" | "glow" | "none";
  /** 媒体随滚动从倾斜摆正 (仅 transform) */
  tilt?: boolean;
  className?: string;
}

/** 媒体: 进视口前带透视倾斜, 滚动到位后摆正. 减弱动效时始终平放. */
function TiltMedia({ children, enabled }: { children: React.ReactNode; enabled: boolean }) {
  const ref = React.useRef<HTMLDivElement>(null);
  const reduce = useReducedMotion();
  const { scrollYProgress } = useScroll({ target: ref, offset: ["start end", "start 0.35"] });
  const rotateX = useTransform(scrollYProgress, [0, 1], [14, 0]);
  const scale = useTransform(scrollYProgress, [0, 1], [0.94, 1]);
  const y = useTransform(scrollYProgress, [0, 1], [24, 0]);
  if (!enabled || reduce) return <div ref={ref}>{children}</div>;
  return (
    <div ref={ref} style={{ perspective: 1600 }}>
      <m.div style={{ rotateX, scale, y, transformOrigin: "50% 0%" }}>{children}</m.div>
    </div>
  );
}

/** 首屏: 公告 → 两句标题 (主句 + 弱化句) → 说明 → 按钮 → 产品界面. */
export function Hero({ eyebrow, title, highlight, description, actions, media, align = "left", backdrop = "none", tilt = true, className }: HeroProps) {
  const center = align === "center";
  return (
    <section className={cn("relative px-5 pt-16 md:px-8 md:pt-24", media ? "pb-0" : "pb-20", className)}>
      {backdrop !== "none" && <Backdrop variant={backdrop} />}
      <div className={cn("relative mx-auto max-w-6xl", center && "text-center")}>
        {eyebrow && (
          <a href={eyebrow.href ?? "#"} className="group mb-8 inline-flex items-center gap-2 text-[13px] text-muted-foreground transition-colors hover:text-foreground">
            <span className="rounded-full border px-2 py-px text-[11px] font-medium text-foreground">新</span>
            {eyebrow.label}
            <ArrowRight className="size-3 transition-transform group-hover:translate-x-0.5" />
          </a>
        )}
        {/* 公告, 标题, 说明, 按钮不做透明度入场: 它们是 LCP, 必须随 HTML 第一帧画出来 */}
        <h1 className={cn("text-balance text-[2.6rem] font-medium leading-[1.06] tracking-[-0.03em] sm:text-6xl md:text-7xl", center ? "mx-auto max-w-4xl" : "max-w-4xl")}>
          {title}
          {highlight && <span className="block text-muted-foreground/70">{highlight}</span>}
        </h1>
        <p className={cn("mt-6 max-w-xl text-pretty text-[17px] leading-relaxed text-muted-foreground md:text-lg", center && "mx-auto")}>{description}</p>
        {actions && <div className={cn("mt-9 flex flex-wrap items-center gap-x-5 gap-y-3", center && "justify-center")}>{actions}</div>}
      </div>
      {media && (
        <Reveal preset="fade" delay={0.2} inView={false} className="relative mx-auto mt-16 max-w-6xl md:mt-20">
          <TiltMedia enabled={tilt}>{media}</TiltMedia>
        </Reveal>
      )}
    </section>
  );
}

import type * as React from "react";
import { cn } from "@/lib/utils";

/** 客户标识墙: 静态网格, 发丝线分格, 单色. 比跑马灯更克制, 也更容易看清. */
export function LogoWall({ label, logos, className }: { label?: React.ReactNode; logos: React.ReactNode[]; className?: string }) {
  return (
    <div className={cn("px-5 md:px-8", className)}>
      <div className="mx-auto max-w-6xl">
        {label && <p className="mb-8 text-sm text-muted-foreground">{label}</p>}
        <div className="grid grid-cols-2 gap-px overflow-hidden border-y bg-border sm:grid-cols-4">
          {logos.map((l, i) => (
            <div key={i} className="flex h-20 items-center justify-center bg-background text-muted-foreground transition-colors hover:text-foreground md:h-24">{l}</div>
          ))}
        </div>
      </div>
    </div>
  );
}

import * as React from "react";
import { Check } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Segmented } from "@sites/_blocks/analytics/segmented";
import { AnimatedNumber } from "@/motion/animated-number";
import { Reveal } from "@/motion/reveal";
import { cn } from "@/lib/utils";

export interface Plan {
  name: string;
  description: string;
  monthly: number;
  /** 按年时的月均价 */
  yearly: number;
  features: string[];
  cta: string;
  featured?: boolean;
  currency?: string;
}

/** 定价: 一整块分栏 (发丝线分隔), 推荐档用浅底区分, 月 / 年切换数字滚动. */
export function Pricing({ plans, yearlyNote = "省 20%", onSelect }: { plans: Plan[]; yearlyNote?: string; onSelect?: (plan: Plan, yearly: boolean) => void }) {
  const [cycle, setCycle] = React.useState<"m" | "y">("y");
  const cols = plans.length === 3 ? "lg:grid-cols-3" : "md:grid-cols-2 lg:grid-cols-4";
  return (
    <div>
      <div className="mb-8 flex">
        <Segmented value={cycle} onChange={setCycle} options={[{ value: "m", label: "按月" }, { value: "y", label: `按年 · ${yearlyNote}` }]} />
      </div>
      <Reveal className={cn("grid gap-px overflow-hidden rounded-xl border bg-border", cols)}>
        {plans.map((p) => (
          <div key={p.name} className={cn("flex flex-col p-7 md:p-8", p.featured ? "bg-muted dark:bg-card" : "bg-background")}>
            <div className="flex items-center justify-between">
              <h3 className="font-medium">{p.name}</h3>
              {p.featured && <span className="text-xs text-muted-foreground">最多团队选择</span>}
            </div>
            <p className="mt-1.5 text-sm text-muted-foreground">{p.description}</p>
            <div className="mt-8 flex items-baseline gap-1 tabular">
              <span className="text-muted-foreground">{p.currency ?? "¥"}</span>
              <AnimatedNumber value={cycle === "m" ? p.monthly : p.yearly} from={cycle === "m" ? p.monthly : p.yearly} duration={0.5} className="text-[2.75rem] font-medium leading-none tracking-[-0.03em]" />
              <span className="text-sm text-muted-foreground">/ 月</span>
            </div>
            <Button type="button" className="mt-8 h-10" variant={p.featured ? "default" : "outline"} onClick={() => onSelect?.(p, cycle === "y")}>{p.cta}</Button>
            <ul className="mt-8 space-y-3 border-t pt-6 text-sm">
              {p.features.map((f) => (
                <li key={f} className="flex gap-2.5"><Check className="mt-0.5 size-4 shrink-0 text-muted-foreground" />{f}</li>
              ))}
            </ul>
          </div>
        ))}
      </Reveal>
    </div>
  );
}

import type * as React from "react";
import { Reveal } from "@/motion/reveal";
import { cn } from "@/lib/utils";

/** 单条大证言: 一句话说服力胜过一墙卡片. aside 放可量化的结果. */
export function Quote({ quote, name, role, avatar, aside, className }: {
  quote: string;
  name: string;
  role: string;
  avatar?: string;
  aside?: React.ReactNode;
  className?: string;
}) {
  return (
    <Reveal className={cn("grid gap-10 md:grid-cols-[minmax(0,1fr)_auto] md:items-end md:gap-16", className)}>
      <figure>
        <blockquote className="max-w-3xl text-pretty text-2xl font-medium leading-snug tracking-[-0.02em] md:text-[2.1rem] md:leading-[1.3]">
          <span aria-hidden className="text-muted-foreground/50">“</span>{quote}<span aria-hidden className="text-muted-foreground/50">”</span>
        </blockquote>
        <figcaption className="mt-8 flex items-center gap-3 text-sm">
          {avatar ? <img src={avatar} alt="" className="size-9 rounded-full object-cover" /> : <span className="grid size-9 place-items-center rounded-full bg-muted font-medium">{name.slice(0, 1)}</span>}
          <span><span className="font-medium">{name}</span><span className="block text-muted-foreground">{role}</span></span>
        </figcaption>
      </figure>
      {aside && <div className="md:border-l md:pl-10">{aside}</div>}
    </Reveal>
  );
}

import type * as React from "react";
import { Reveal } from "@/motion/reveal";
import { cn } from "@/lib/utils";

/** 发丝线交点上的十字标记, 用于分区线两端. 只在 xl 以上显示: 更窄时页面栏线贴边, 十字会撑出横向滚动 */
function Cross({ className }: { className?: string }) {
  return (
    <svg aria-hidden viewBox="0 0 11 11" className={cn("absolute hidden size-[11px] text-muted-foreground/60 xl:block", className)}>
      <path d="M5.5 0v11M0 5.5h11" stroke="currentColor" strokeWidth="1" />
    </svg>
  );
}

/**
 * 区块容器: 统一宽度与垂直节奏 + 标题组.
 * - layout="stack": 标题在上 (默认); "split": 标题左侧吸顶, 内容在右, 适合 FAQ / 长说明.
 * - divider: 顶部发丝线 + 两端十字, 配合页面两侧竖线形成版式骨架.
 */
export function Section({ id, eyebrow, title, description, align = "left", layout = "stack", divider = false, className, children }: {
  id?: string;
  eyebrow?: string;
  title?: React.ReactNode;
  description?: React.ReactNode;
  align?: "center" | "left";
  layout?: "stack" | "split";
  divider?: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  const head = (title || eyebrow) && (
    <Reveal className={cn(layout === "split" ? "md:sticky md:top-24 md:self-start" : "mb-12 md:mb-16", align === "center" && layout === "stack" ? "mx-auto max-w-2xl text-center" : "max-w-2xl")}>
      {eyebrow && <div className="mb-4 font-mono text-xs text-muted-foreground">{eyebrow}</div>}
      {title && <h2 className="text-balance text-3xl font-medium leading-[1.12] tracking-[-0.03em] md:text-[2.75rem]">{title}</h2>}
      {description && <p className="mt-5 max-w-xl text-pretty leading-relaxed text-muted-foreground md:text-[17px]">{description}</p>}
    </Reveal>
  );
  return (
    <section id={id} className={cn("relative scroll-mt-16 px-5 py-20 md:px-8 md:py-28", divider && "border-t", className)}>
      {divider && <><Cross className="-left-[6px] -top-[6px]" /><Cross className="-right-[6px] -top-[6px]" /></>}
      <div className={cn("mx-auto max-w-6xl", layout === "split" && "grid gap-10 md:grid-cols-[minmax(0,5fr)_minmax(0,7fr)] md:gap-16")}>
        {head}
        <div className="min-w-0">{children}</div>
      </div>
    </section>
  );
}

import type * as React from "react";
import { cn } from "@/lib/utils";

/** 站点页脚: 品牌 + 多列链接 + 底部版权行. 手机上链接两列并排, 不一路竖排到底. */
export function SiteFooter({ brand, columns, note, legal, width = "max-w-6xl" }: {
  brand: React.ReactNode;
  columns: { title: string; links: { label: string; href: string }[] }[];
  note?: string;
  legal?: React.ReactNode;
  /** 内容宽度, 与顶栏和页面栏线对齐. 默认 max-w-6xl */
  width?: string;
}) {
  return (
    <footer className="border-t">
      <div
        className={cn("mx-auto grid grid-cols-2 gap-x-6 gap-y-10 px-5 py-14 md:grid-cols-[2fr_repeat(var(--cols),1fr)] md:px-8", width)}
        style={{ "--cols": columns.length } as React.CSSProperties}
      >
        <div className="col-span-2 space-y-3 md:col-span-1">
          <div className="font-semibold tracking-tight">{brand}</div>
          {note && <p className="max-w-xs text-sm leading-relaxed text-muted-foreground">{note}</p>}
        </div>
        {columns.map((c) => (
          <nav key={c.title} aria-label={c.title}>
            <div className="mb-4 text-[13px] font-medium">{c.title}</div>
            <ul className="space-y-2.5 text-[13px] text-muted-foreground">
              {c.links.map((l) => <li key={l.label}><a href={l.href} className="transition-colors hover:text-foreground">{l.label}</a></li>)}
            </ul>
          </nav>
        ))}
      </div>
      {legal && <div className={cn("mx-auto px-5 md:px-8", width)}><div className="border-t py-6 text-xs text-muted-foreground">{legal}</div></div>}
    </footer>
  );
}

import * as React from "react";
import { Sheet, SheetContent, SheetDescription, SheetTitle } from "@/components/ui/sheet";

/** 页内锚点: 平滑滚到目标, 不改 hash. 减弱动效时直接跳. */
function scrollToHash(href: string) {
  if (!href.startsWith("#") || href.startsWith("#/") || href === "#") return false;
  const el = document.getElementById(decodeURIComponent(href.slice(1)));
  if (!el) return false;
  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  el.scrollIntoView({ behavior: reduce ? "auto" : "smooth", block: "start" });
  return true;
}

/**
 * 手机菜单: 顶部抽屉. 由 SiteHeader 第一次点开时才加载, 首屏不带 Sheet 的代码.
 * 点链接先关抽屉, 关完再滚动, 避免和滚动锁打架; 没有滚动时焦点回到菜单按钮.
 */
export default function SiteHeaderMenu({ brand, open, onOpenChange, links, menuActions, trigger }: {
  brand: React.ReactNode;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  links: { label: string; href: string }[];
  menuActions?: React.ReactNode;
  trigger: React.RefObject<HTMLButtonElement | null>;
}) {
  const pending = React.useRef<string | null>(null);
  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="top"
        className="gap-0 px-5 pb-6"
        onCloseAutoFocus={(e) => {
          e.preventDefault();
          const href = pending.current;
          pending.current = null;
          if (!(href && scrollToHash(href))) trigger.current?.focus();
        }}
      >
        {/* 抽屉盖住了顶栏, 品牌放回同一位置, 视觉上顶栏没动 */}
