              key={l.href + l.label}
              href={l.href}
              onClick={(e) => {
                if (l.href.startsWith("#") && !l.href.startsWith("#/")) {
                  e.preventDefault();
                  e.stopPropagation();
                  pending.current = l.href;
                }
                onOpenChange(false);
              }}
              className="border-b py-3.5 text-[15px] transition-colors hover:text-muted-foreground"
