import { Moon, Sun } from "lucide-react";
import { flushSync } from "react-dom";
import { Button } from "@/components/ui/button";
import { useTheme } from "@/hooks/use-theme";
import { cn } from "@/lib/utils";

type ViewTransitionDoc = Document & { startViewTransition?: (cb: () => void) => { ready: Promise<void> } };

/**
 * 轻量亮暗切换: 不依赖弹层, 首屏可用.
 * 支持 View Transitions 的浏览器里, 新主题从点击处圆形展开; 减弱动效时直接切换.
 * 需要强调色等更多选项时用 ThemeMenu.
 */
export function ThemeToggle({ className }: { className?: string }) {
  const { setMode } = useTheme();

  // 图标和下一档都从 <html class="dark"> 读, 不从 React 状态读: 预渲染的 HTML 与客户端一致, 不会水合不匹配
  const onClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    const next = document.documentElement.classList.contains("dark") ? "light" : "dark";
    const doc = document as ViewTransitionDoc;
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (!doc.startViewTransition || reduce) {
      setMode(next);
      return;
    }
    const { clientX: x, clientY: y } = e;
    const r = Math.hypot(Math.max(x, innerWidth - x), Math.max(y, innerHeight - y));
    const vt = doc.startViewTransition(() => flushSync(() => setMode(next)));
    void vt.ready.then(() => {
      document.documentElement.animate(
        { clipPath: [`circle(0px at ${x}px ${y}px)`, `circle(${r}px at ${x}px ${y}px)`] },
        { duration: 480, easing: "cubic-bezier(0.22, 1, 0.36, 1)", pseudoElement: "::view-transition-new(root)" },
      );
    });
  };

  return (
    <Button type="button" variant="ghost" size="icon" className={cn("size-9", className)} aria-label="切换亮色 / 暗色" onClick={onClick}>
      <Sun className="size-4 dark:hidden" />
      <Moon className="hidden size-4 dark:block" />
    </Button>
  );
}

/*
 * Tally 发布页美术方向: 暖白纸面 + 墨色 + 发丝线, 招牌视觉是"纸面舞台上的真实对账工作台".
 * 只在 <html data-site="launch"> 下生效 (页面挂载时自动加上), 不影响别的页面.
 * 暗色是"夜间的账本": 偏暖的炭黑, 不是冷蓝黑.
 */
@import "@fontsource-variable/inter";

:root[data-site="launch"] {
  --background: oklch(0.985 0.004 85);
  --foreground: oklch(0.2 0.008 70);
  --card: oklch(0.995 0.002 85);
  --popover: oklch(0.995 0.002 85);
  --primary: oklch(0.22 0.008 70);
  --primary-foreground: oklch(0.985 0.004 85);
  --secondary: oklch(0.955 0.006 85);
  --secondary-foreground: oklch(0.22 0.008 70);
  --muted: oklch(0.955 0.006 85);
  --muted-foreground: oklch(0.5 0.014 70);
  --accent: oklch(0.945 0.007 85);
  --accent-foreground: oklch(0.22 0.008 70);
  --border: oklch(0.905 0.008 85);
  --input: oklch(0.89 0.009 85);
  --ring: oklch(0.6 0.02 70);
  /* 默认红在暖纸面上对比度不够 4.5:1, 压暗一档 */
  --destructive: oklch(0.52 0.2 27);
  --radius: 0.625rem;

  /* 舞台: 比页面深半档的纸色 + 8px 发丝网格 */
  --stage: oklch(0.962 0.007 85);
  --stage-line: oklch(0.2 0.01 70 / 0.05);
}

:root.dark[data-site="launch"] {
  --background: oklch(0.165 0.006 70);
  --foreground: oklch(0.95 0.006 85);
  --card: oklch(0.195 0.007 70);
  --popover: oklch(0.21 0.007 70);
  --primary: oklch(0.95 0.006 85);
  --primary-foreground: oklch(0.18 0.006 70);
  --secondary: oklch(0.24 0.008 70);
  --secondary-foreground: oklch(0.95 0.006 85);
  --muted: oklch(0.235 0.008 70);
  --muted-foreground: oklch(0.68 0.012 80);
  --accent: oklch(0.25 0.008 70);
  --accent-foreground: oklch(0.95 0.006 85);
  --border: oklch(0.28 0.008 70);
  --input: oklch(0.31 0.008 70);
  --ring: oklch(0.55 0.02 80);
  --destructive: oklch(0.7 0.19 25);

  --stage: oklch(0.19 0.007 70);
  --stage-line: oklch(0.95 0.01 85 / 0.045);
}

[data-site="launch"] .launch-stage {
  background-color: var(--stage);
  background-image:
    linear-gradient(var(--stage-line) 1px, transparent 1px),
    linear-gradient(90deg, var(--stage-line) 1px, transparent 1px);
  background-size: 8px 8px;
  background-position: -1px -1px;
}

