 * 演示用: 邮箱以 @fail.test 结尾时模拟失败, 方便看失败态.
 */
export async function submitTrial(data: { email: string; company: string; intent: TrialIntent }): Promise<void> {
  await new Promise((r) => setTimeout(r, 900));
