import * as React from "react";
import { animate, useInView, useMotionValue } from "motion/react";
import { useReducedMotion } from "@/motion/use-reduced-motion";
import { cn } from "@/lib/utils";

interface AnimatedNumberProps extends React.HTMLAttributes<HTMLSpanElement> {
  value: number;
  /** Intl.NumberFormat 选项, 例如 { style: "currency", currency: "CNY" } */
  format?: Intl.NumberFormatOptions;
  locale?: string;
  /** 首次从 0 开始 (默认). 之后数值变化都从当前值继续, 不重播. */
  from?: number;
  duration?: number;
}

/**
 * 弹簧数字: 进入视口时滚到目标值, 之后 value 变化从当前值继续.
 * 等宽数字, 不抖; 读屏只读终值; 减弱动效直接显示终值.
 */
export function AnimatedNumber({ value, format, locale = "zh-CN", from = 0, duration = 1.2, className, ...rest }: AnimatedNumberProps) {
  const ref = React.useRef<HTMLSpanElement>(null);
  const inView = useInView(ref, { once: true, margin: "0px 0px -10% 0px" });
  const reduce = useReducedMotion();
  // 减弱动效: 直接从终值起步, 不等进入视口
  const start = reduce ? value : from;
  const mv = useMotionValue(start);
  const fmt = React.useMemo(() => new Intl.NumberFormat(locale, format), [locale, format]);

  React.useEffect(() => {
    // 减弱动效: 不等进入视口, 直接终值 (水合后 reduce 才变 true, 所以放在 effect 里)
    if (reduce) {
      mv.set(value);
      return;
    }
    if (!inView) return;
    const controls = animate(mv, value, { duration, ease: [0.22, 1, 0.36, 1] });
    return () => controls.stop();
  }, [inView, value, reduce, duration, mv]);

  React.useEffect(() => mv.on("change", (v) => {
    if (ref.current) ref.current.textContent = fmt.format(v);
  }), [mv, fmt]);

  return (
    <span className={cn("tabular", className)} {...rest}>
      <span ref={ref} aria-hidden>{fmt.format(start)}</span>
      <span className="sr-only">{fmt.format(value)}</span>
    </span>
  );
}

import type { Transition, Variants } from "motion/react";

/** 弹簧档位: 统一手感, 组件里不写裸数字. */
export const spring = {
  /** 按压 / 小控件: 快, 几乎不过冲 */
  snappy: { type: "spring", stiffness: 520, damping: 34, mass: 0.8 },
  /** 默认: 入场 / 布局变化 */
  smooth: { type: "spring", stiffness: 260, damping: 30 },
  /** 有弹性: 徽标 / 数字 / 强调 */
  bouncy: { type: "spring", stiffness: 300, damping: 16 },
  /** 慢跟随: 指针跟随 / 视差 */
  follow: { type: "spring", stiffness: 150, damping: 20, mass: 0.6 },
} satisfies Record<string, Transition>;

export const ease = {
  out: [0.22, 1, 0.36, 1],
  inOut: [0.65, 0, 0.35, 1],
} as const;

export const duration = { fast: 0.15, base: 0.25, slow: 0.5 } as const;

export type RevealPreset = "fade" | "up" | "down" | "left" | "right" | "scale" | "blur";

const OFFSET = 24;

/** 入场预设: 只动 opacity / transform / filter. */
export const reveal: Record<RevealPreset, Variants> = {
  fade: { hidden: { opacity: 0 }, show: { opacity: 1 } },
  up: { hidden: { opacity: 0, y: OFFSET }, show: { opacity: 1, y: 0 } },
  down: { hidden: { opacity: 0, y: -OFFSET }, show: { opacity: 1, y: 0 } },
  left: { hidden: { opacity: 0, x: OFFSET }, show: { opacity: 1, x: 0 } },
  right: { hidden: { opacity: 0, x: -OFFSET }, show: { opacity: 1, x: 0 } },
  scale: { hidden: { opacity: 0, scale: 0.94 }, show: { opacity: 1, scale: 1 } },
  blur: { hidden: { opacity: 0, filter: "blur(10px)", y: 8 }, show: { opacity: 1, filter: "blur(0px)", y: 0 } },
};

import type * as React from "react";
import { LazyMotion, MotionConfig } from "motion/react";

// 动画特性包异步加载: 首屏只带 m 组件骨架 (~5KB), 完整特性 (含 layout / 拖拽) 在空闲时补上
const loadFeatures = () => import("./features").then((r) => r.default);

/**
 * 应用根部包一次. 组件内一律用 m.div 而不是 motion.div.
 * reducedMotion="user": 系统开了减弱动效时, 所有位移 / 缩放 / 布局动画直接到终态, 只保留淡入淡出.
 */
export function MotionProvider({ children }: { children: React.ReactNode }) {
  return (
    <MotionConfig reducedMotion="user">
      <LazyMotion features={loadFeatures} strict>{children}</LazyMotion>
    </MotionConfig>
  );
}

import { m, type HTMLMotionProps } from "motion/react";
import { useReducedMotion } from "@/motion/use-reduced-motion";
import { reveal, spring, type RevealPreset } from "./presets";

interface RevealProps extends Omit<HTMLMotionProps<"div">, "variants" | "initial" | "animate"> {
  preset?: RevealPreset;
  delay?: number;
  /** 进入视口才播放 (默认). false 时挂载即播. */
  inView?: boolean;
  /** 只播一次 (默认 true) */
  once?: boolean;
}

/**
 * 视口内入场. 减弱动效时直接显示终态.
 * 结构始终不变 (同一个 m.div, 同一个 initial), 只换触发方式: 预渲染与水合一致,
 * 水合后得知要减弱动效时, 以 0 时长切到终态.
 */
export function Reveal({ preset = "up", delay = 0, inView = true, once = true, transition, ...rest }: RevealProps) {
  const reduce = useReducedMotion();
  const trigger = reduce
    ? { animate: "show" }
    : inView
      ? { whileInView: "show", viewport: { once, margin: "0px 0px -10% 0px" } }
      : { animate: "show" };
  return (
    <m.div
      variants={reveal[preset]}
      initial="hidden"
      {...trigger}
      transition={reduce ? { duration: 0 } : { ...spring.smooth, delay, ...transition }}
      {...rest}
    />
  );
}

interface StaggerProps extends Omit<HTMLMotionProps<"div">, "variants" | "initial"> {
  /** 首项间隔 (秒). 后续间隔逐渐缩短, 群体入场越来越快, 不是匀速. */
  gap?: number;
  delay?: number;
  once?: boolean;
}

/** 子项交错入场, 配合 <StaggerItem>. */
export function Stagger({ gap = 0.08, delay = 0, once = true, ...rest }: StaggerProps) {
  const reduce = useReducedMotion();
  return (
    <m.div
      initial="hidden"
      {...(reduce ? { animate: "show" } : { whileInView: "show", viewport: { once, margin: "0px 0px -10% 0px" } })}
      variants={{ hidden: {}, show: { transition: reduce ? { duration: 0 } : { staggerChildren: gap, delayChildren: delay } } }}
      {...rest}
    />
  );
}

export function StaggerItem({ preset = "up", ...rest }: Omit<HTMLMotionProps<"div">, "variants"> & { preset?: RevealPreset }) {
  return <m.div variants={reveal[preset]} transition={spring.smooth} {...rest} />;
}

export type { RevealProps, StaggerProps };

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(cb: () => void) {
  const mq = window.matchMedia(QUERY);
  mq.addEventListener("change", cb);
  return () => mq.removeEventListener("change", cb);
}

/**
 * 用户是否要求减弱动效. 代替 motion 的 useReducedMotion:
 * 服务端和水合那一帧固定返回 false, 水合后再换成真实值,
 * 预渲染的 HTML 与客户端第一帧一致, 不会水合不匹配.
 */
export function useReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, () => window.matchMedia(QUERY).matches, () => false);
}

/*
 * 特效层的关键帧与工具类. 只动 transform / opacity / background-position, 不触发布局.
 * 全部在 prefers-reduced-motion 下由 globals.css 统一停掉.
 */

@theme {
  --animate-marquee: hx-marquee var(--marquee-duration, 40s) linear infinite;
  --animate-marquee-vertical: hx-marquee-y var(--marquee-duration, 40s) linear infinite;
  --animate-shimmer: hx-shimmer 2.4s var(--ease-in-out, ease-in-out) infinite;
  --animate-aurora: hx-aurora 18s ease-in-out infinite alternate;
  --animate-beam: hx-beam var(--beam-duration, 6s) linear infinite;
  --animate-pulse-ring: hx-pulse-ring 2s cubic-bezier(0.22, 1, 0.36, 1) infinite;
  --animate-float: hx-float 6s ease-in-out infinite;

  @keyframes hx-marquee { from { transform: translateX(0); } to { transform: translateX(calc(-100% - var(--marquee-gap, 2.5rem))); } }
  @keyframes hx-marquee-y { from { transform: translateY(0); } to { transform: translateY(calc(-100% - var(--marquee-gap, 2.5rem))); } }
  @keyframes hx-shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
  @keyframes hx-aurora {
    0% { transform: translate3d(-8%, -4%, 0) rotate(0deg) scale(1); }
    50% { transform: translate3d(6%, 4%, 0) rotate(8deg) scale(1.1); }
    100% { transform: translate3d(-4%, 6%, 0) rotate(-6deg) scale(1.05); }
  }
  @keyframes hx-beam { to { --beam-angle: 360deg; } }
  @keyframes hx-pulse-ring { 0% { transform: scale(0.8); opacity: 0.7; } 100% { transform: scale(2.2); opacity: 0; } }
  @keyframes hx-float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-8px); } }
}

@property --beam-angle {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}

@layer components {
/* 沿边框流动的光: 背景用 conic-gradient, 用 mask 只露出 1px 边 */
.hx-beam {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: var(--beam-width, 1px);
  background: conic-gradient(from var(--beam-angle), transparent 0deg 300deg, var(--beam-color, var(--brand)) 340deg, transparent 360deg);
  mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
  pointer-events: none;
}

/* 指针光斑: 由 JS 写入 --mx / --my */
.hx-spotlight::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(var(--spot-size, 420px) circle at var(--mx, 50%) var(--my, 50%), var(--spot-color, var(--brand-soft)), transparent 70%);
  opacity: var(--spot-opacity, 0);
  transition: opacity var(--dur-base) var(--ease-out);
  pointer-events: none;
}

/* 底纹: 网格 / 点阵, 自带边缘淡出 */
.hx-grid {
  background-image:
    linear-gradient(to right, color-mix(in oklch, var(--foreground) 7%, transparent) 1px, transparent 1px),
    linear-gradient(to bottom, color-mix(in oklch, var(--foreground) 7%, transparent) 1px, transparent 1px);
  background-size: var(--grid-size, 48px) var(--grid-size, 48px);
}
.hx-dots {
  background-image: radial-gradient(color-mix(in oklch, var(--foreground) 16%, transparent) 1px, transparent 1px);
  background-size: var(--grid-size, 22px) var(--grid-size, 22px);
}
.hx-fade-edges { mask-image: radial-gradient(ellipse at center, #000 30%, transparent 75%); }
.hx-fade-bottom { mask-image: linear-gradient(to bottom, #000 55%, transparent); }

/* 渐变描边文字 (只用于标题) */
.hx-text-gradient {
  background: linear-gradient(120deg, var(--foreground) 20%, color-mix(in oklch, var(--brand) 85%, var(--foreground)) 60%, var(--foreground) 90%);
  background-size: 200% auto;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.hx-shimmer-text {
  background: linear-gradient(90deg, var(--muted-foreground) 35%, var(--foreground) 50%, var(--muted-foreground) 65%);
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* 噪点: 用内联 SVG, 给大色块加质感 */
.hx-noise::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: var(--noise-opacity, 0.06);
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
  mix-blend-mode: overlay;
}
}

/* ThemeToggle 圆形展开: 关掉默认交叉淡入, 由脚本驱动 clip-path */
::view-transition-old(root),
::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
}

@theme {
  @keyframes hx-progress { from { transform: scaleX(0); } to { transform: scaleX(1); } }
}

@import "tailwindcss";
@import "tw-animate-css";
@import "./effects.css";

/*
 * HX-UI 2 设计令牌
 * - 变量名与 shadcn/ui 主题格式完全一致: 任何 shadcn 主题 (tweakcn 等) 的 :root / .dark 块可以直接粘贴覆盖.
 * - 颜色用 OKLCH, 亮暗两套; 强调色可用 data-theme 切换 (zinc 默认 / indigo / emerald / rose / amber).
 * - 动效时长与缓动也是令牌, 组件与 motion 预设都从这里读.
 */

@custom-variant dark (&:is(.dark *));

:root {
  --radius: 0.75rem;

  --background: oklch(0.995 0 0);
  --foreground: oklch(0.17 0.005 270);
  --card: oklch(1 0 0);
  --card-foreground: var(--foreground);
  --popover: oklch(1 0 0);
  --popover-foreground: var(--foreground);
  --primary: oklch(0.21 0.006 270);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.967 0.002 270);
  --secondary-foreground: oklch(0.21 0.006 270);
  --muted: oklch(0.967 0.002 270);
  --muted-foreground: oklch(0.52 0.012 270);
  --accent: oklch(0.955 0.004 270);
  --accent-foreground: oklch(0.21 0.006 270);
  --destructive: oklch(0.58 0.22 27);
  --success: oklch(0.63 0.16 152);
  --warning: oklch(0.76 0.16 70);
  --info: oklch(0.62 0.17 250);
  --border: oklch(0.92 0.004 270);
  --input: oklch(0.92 0.004 270);
  --ring: oklch(0.65 0.02 270);

  /* 品牌强调色: 特效 / 图表首色 / 高亮读这一组 */
  --brand: oklch(0.58 0.2 275);
  --brand-foreground: oklch(0.985 0 0);
  --brand-soft: oklch(0.58 0.2 275 / 0.12);

  --chart-1: var(--brand);
  --chart-2: oklch(0.7 0.14 190);
  --chart-3: oklch(0.75 0.15 75);
  --chart-4: oklch(0.65 0.2 330);
  --chart-5: oklch(0.6 0.12 150);

  --sidebar: oklch(0.985 0.001 270);
  --sidebar-foreground: var(--foreground);
  --sidebar-primary: var(--primary);
  --sidebar-primary-foreground: var(--primary-foreground);
  --sidebar-accent: var(--accent);
  --sidebar-accent-foreground: var(--accent-foreground);
  --sidebar-border: var(--border);
  --sidebar-ring: var(--ring);

  --shadow-soft: 0 1px 2px oklch(0 0 0 / 0.04), 0 4px 16px -4px oklch(0 0 0 / 0.08);
  --shadow-float: 0 2px 6px oklch(0 0 0 / 0.05), 0 24px 48px -12px oklch(0 0 0 / 0.18);

  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
  --dur-fast: 150ms;
  --dur-base: 250ms;
  --dur-slow: 500ms;
}

.dark {
  --background: oklch(0.145 0.004 270);
  --foreground: oklch(0.97 0.002 270);
  --card: oklch(0.18 0.005 270);
  --card-foreground: var(--foreground);
  --popover: oklch(0.2 0.006 270);
  --popover-foreground: var(--foreground);
  --primary: oklch(0.96 0.002 270);
  --primary-foreground: oklch(0.18 0.005 270);
  --secondary: oklch(0.25 0.006 270);
  --secondary-foreground: var(--foreground);
  --muted: oklch(0.23 0.006 270);
  --muted-foreground: oklch(0.7 0.012 270);
  --accent: oklch(0.26 0.008 270);
  --accent-foreground: var(--foreground);
  --destructive: oklch(0.68 0.2 25);
  --success: oklch(0.72 0.16 152);
  --warning: oklch(0.8 0.15 75);
  --info: oklch(0.7 0.15 250);
  --border: oklch(1 0 0 / 0.09);
  --input: oklch(1 0 0 / 0.12);
  --ring: oklch(0.55 0.02 270);

  --brand: oklch(0.68 0.19 275);
  --brand-soft: oklch(0.68 0.19 275 / 0.16);

  --sidebar: oklch(0.165 0.005 270);

  --shadow-soft: 0 1px 2px oklch(0 0 0 / 0.3), 0 4px 16px -4px oklch(0 0 0 / 0.4);
  --shadow-float: 0 2px 6px oklch(0 0 0 / 0.3), 0 24px 48px -12px oklch(0 0 0 / 0.6);
}

/* 强调色预设: 只换 brand, 中性色不动 */
[data-theme="indigo"] { --brand: oklch(0.58 0.2 275); }
[data-theme="emerald"] { --brand: oklch(0.62 0.15 160); }
[data-theme="rose"] { --brand: oklch(0.62 0.21 12); }
[data-theme="amber"] { --brand: oklch(0.72 0.16 65); }
[data-theme="zinc"] { --brand: oklch(0.45 0.01 270); }
.dark[data-theme="emerald"], .dark [data-theme="emerald"] { --brand: oklch(0.72 0.15 160); }
.dark[data-theme="rose"], .dark [data-theme="rose"] { --brand: oklch(0.7 0.19 12); }
.dark[data-theme="zinc"], .dark [data-theme="zinc"] { --brand: oklch(0.8 0.01 270); }

@theme inline {
  --font-sans: "Inter Variable", "Inter", ui-sans-serif, system-ui, -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;

  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 10px);

  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-info: var(--info);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-brand: var(--brand);
  --color-brand-foreground: var(--brand-foreground);
  --color-brand-soft: var(--brand-soft);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  --shadow-soft: var(--shadow-soft);
  --shadow-float: var(--shadow-float);
  --ease-out: var(--ease-out);
  --ease-spring: var(--ease-spring);
}

@layer base {
  * { @apply border-border outline-ring/50; }
  html { -webkit-font-smoothing: antialiased; text-rendering: optimizeLegibility; }
  body { @apply bg-background text-foreground font-sans; font-feature-settings: "cv11", "ss01"; }
  ::selection { background: var(--brand-soft); }
  .tabular { font-variant-numeric: tabular-nums; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
